@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  --primary: #F02D00;
  --dark: #171717;
  --dark-gray: #2A2A2A;
  --light: #FFFFFF;
  --gray-100: #F5F5F5;
  --gray-200: #E5E5E5;
  --gray-600: #666666;
  --accent: #00FF66; /* Electric green */
  --accent-teal: #00E5FF; /* Vibrant teal */
  --font-main: 'Inter', sans-serif;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 24px;
  --shadow: 0 4px 20px rgba(0,0,0,0.08);
  --shadow-hover: 0 12px 30px rgba(0,0,0,0.15);
  --transition: all 0.3s ease;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-main);
  background-color: var(--light);
  color: var(--dark);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 5%;
}

/* Utilities */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  border: none;
  font-size: 1rem;
}
.btn-primary { background-color: var(--primary); color: var(--light); }
.btn-primary:hover { background-color: #d02600; transform: translateY(-2px); }
.btn-dark { background-color: var(--dark); color: var(--light); }
.btn-dark:hover { background-color: #000; transform: translateY(-2px); }
.btn-outline { border: 2px solid var(--dark); background: transparent; color: var(--dark); }
.btn-outline:hover { background: var(--dark); color: var(--light); }
.btn-lg { padding: 1rem 2rem; font-size: 1.125rem; }

.badge {
  display: inline-block;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 800;
  text-transform: uppercase;
}
.badge-discount { background-color: var(--accent); color: var(--dark); }
.badge-plus { background-color: var(--dark); color: var(--accent); }
.badge-teal { background-color: var(--accent-teal); color: var(--dark); }

/* Typography */
h1, h2, h3, h4, h5 {
  color: var(--dark);
  font-weight: 800;
  letter-spacing: -0.02em;
}
h1 { font-size: 3.5rem; line-height: 1.1; margin-bottom: 1.5rem; }
h2 { font-size: 2.5rem; margin-bottom: 1rem; }
h3 { font-size: 1.5rem; margin-bottom: 0.5rem; }
.text-muted { color: var(--gray-600); }

/* Banner & Header */
.top-banner {
  background-color: var(--primary);
  color: var(--light);
  text-align: center;
  padding: 0.75rem;
  font-size: 0.875rem;
  font-weight: 600;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 1rem;
}
.close-banner {
  position: absolute;
  right: 1.5rem;
  background: none;
  border: none;
  color: white;
  cursor: pointer;
  font-size: 1.25rem;
}

header {
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  background: rgba(255, 255, 255, 0.98);
  backdrop-filter: blur(10px);
  z-index: 100;
}
.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 80px;
}
.logo { font-size: 1.5rem; font-weight: 800; letter-spacing: -0.5px; }
.logo span { color: var(--primary); }
.nav-links { display: flex; gap: 2rem; align-items: center; margin-left: 2rem; }
.nav-links a { font-weight: 600; font-size: 0.95rem; transition: color 0.2s; }
.nav-links a:hover { color: var(--primary); }
.nav-links a.active { color: var(--primary); }
.search-bar {
  background: var(--gray-100);
  border-radius: 50px;
  padding: 0.5rem 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex: 1;
  max-width: 300px;
  margin-left: auto;
  margin-right: 2rem;
}
.search-bar input { border: none; background: transparent; outline: none; width: 100%; font-family: var(--font-main); }
.nav-actions { display: flex; align-items: center; gap: 1rem; }

/* Hero Sections */
.hero {
  padding: 5rem 0;
  background: var(--dark);
  color: var(--light);
  overflow: hidden;
}
.hero h1 { color: var(--light); }
.hero-content { max-width: 600px; margin-bottom: 3rem; }

/* Carousels */
.carousel-section { padding: 4rem 0; position: relative; }
.carousel-header { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 2rem; }
.carousel-container { position: relative; }
.carousel-track {
  display: flex;
  gap: 1.5rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding: 1rem 0 2rem;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-item {
  scroll-snap-align: start;
  flex: 0 0 calc(25% - 1.125rem);
  background: var(--light);
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}
.carousel-item.large { flex: 0 0 calc(40% - 1.125rem); }
.carousel-item:hover { transform: translateY(-5px); box-shadow: var(--shadow-hover); border-color: transparent; }
.carousel-img {
  height: 200px;
  background-color: var(--dark);
  position: relative;
  overflow: hidden;
  border-radius: var(--radius-md) var(--radius-md) 0 0;
}
.carousel-img img { width: 100%; height: 100%; object-fit: cover; opacity: 0.9; }
.carousel-content { padding: 1.5rem; flex: 1; display: flex; flex-direction: column; }
.carousel-content h3 { font-size: 1.125rem; margin-bottom: 0.5rem; }
.course-meta { display: flex; align-items: center; flex-wrap: wrap; gap: 1rem; font-size: 0.875rem; color: var(--gray-600); margin: 0.5rem 0; }
.course-price { margin-top: auto; display: flex; align-items: center; gap: 0.75rem; font-size: 1.25rem; font-weight: 800; padding-top: 1rem; border-top: 1px solid var(--gray-100); }
.original-price { text-decoration: line-through; color: var(--gray-600); font-size: 0.875rem; font-weight: 500; }
.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 48px; height: 48px; border-radius: 50%;
  background: var(--light); border: 1px solid var(--gray-200);
  box-shadow: var(--shadow); display: flex; align-items: center; justify-content: center;
  cursor: pointer; z-index: 10; transition: var(--transition);
}
.carousel-btn:hover { background: var(--dark); color: var(--light); }
.carousel-btn.prev { left: -24px; }
.carousel-btn.next { right: -24px; }

/* Grid */
.course-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 2rem;
}

/* Value Props */
.value-props { padding: 5rem 0; background: var(--gray-100); }
.vp-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 3rem; margin-top: 3rem; }
.vp-item h4 { font-size: 1.25rem; margin-bottom: 0.5rem; }

/* Layouts (Sidebar) */
.page-layout { display: flex; gap: 3rem; padding: 3rem 0; }
.sidebar { width: 250px; flex-shrink: 0; }
.main-content { flex: 1; }
.filter-group { margin-bottom: 2rem; }
.filter-group h4 { margin-bottom: 1rem; font-size: 1rem; text-transform: uppercase; letter-spacing: 0.05em; color: var(--gray-600); }
.filter-list li { margin-bottom: 0.5rem; }
.filter-list button { background: none; border: none; font-size: 0.95rem; color: var(--dark); cursor: pointer; text-align: left; padding: 0.25rem 0; width: 100%; transition: color 0.2s; }
.filter-list button:hover, .filter-list button.active { color: var(--primary); font-weight: 600; }

/* Plus Pricing */
.pricing-section { padding: 5rem 0; text-align: center; }
.pricing-toggle {
  display: inline-flex; background: var(--gray-100); border-radius: 50px; padding: 0.5rem; margin: 2rem 0;
}
.pricing-toggle button {
  background: transparent; border: none; padding: 0.75rem 2rem; border-radius: 50px; font-weight: 600; font-size: 1rem; cursor: pointer; transition: var(--transition); color: var(--gray-600);
}
.pricing-toggle button.active { background: var(--dark); color: var(--light); box-shadow: var(--shadow); }
.pricing-card {
  max-width: 500px; margin: 0 auto; background: var(--light); border: 2px solid var(--dark); border-radius: var(--radius-lg); padding: 3rem; box-shadow: var(--shadow-hover);
}
.price-display { font-size: 4rem; font-weight: 800; line-height: 1; margin: 1.5rem 0; }
.price-display span { font-size: 1.25rem; color: var(--gray-600); font-weight: 500; }

/* FAQ Accordion */
.faq-section { max-width: 800px; margin: 4rem auto; }
.faq-item { border-bottom: 1px solid var(--gray-200); padding: 1.5rem 0; }
.faq-question {
  display: flex; justify-content: space-between; align-items: center; cursor: pointer; width: 100%; text-align: left; background: none; border: none; font-size: 1.125rem; font-weight: 700; color: var(--dark); font-family: var(--font-main);
}
.faq-icon { font-size: 1.5rem; transition: transform 0.3s; }
.faq-item.active .faq-icon { transform: rotate(45deg); }
.faq-answer { display: none; padding-top: 1rem; color: var(--gray-600); }
.faq-item.active .faq-answer { display: block; }

/* Projects Masonry */
.projects-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 2rem; flex-wrap: wrap; gap: 1rem; }
.project-filters { display: flex; gap: 1rem; flex-wrap: wrap; }
.filter-select { padding: 0.5rem 1rem; border-radius: var(--radius-sm); border: 1px solid var(--gray-200); background: var(--light); font-family: var(--font-main); font-weight: 500; cursor: pointer; }
.masonry-grid { column-count: 3; column-gap: 1.5rem; }
.masonry-item { break-inside: avoid; margin-bottom: 1.5rem; background: var(--light); border-radius: var(--radius-md); overflow: hidden; transition: var(--transition); border: 1px solid var(--gray-200); cursor: pointer; }
.masonry-item:hover { transform: translateY(-5px); box-shadow: var(--shadow-hover); }
.masonry-img { width: 100%; display: block; background: var(--dark); min-height: 200px; }
.masonry-content { padding: 1rem; }
.masonry-content h4 { margin-bottom: 0.25rem; }
.project-stats { display: flex; gap: 1rem; font-size: 0.875rem; color: var(--gray-600); margin-top: 0.5rem; }

/* Login Form */
.login-page { min-height: calc(100vh - 80px); display: flex; align-items: center; justify-content: center; background: var(--gray-100); padding: 2rem; }
.login-card { background: var(--light); padding: 3rem; border-radius: var(--radius-lg); box-shadow: var(--shadow); width: 100%; max-width: 450px; text-align: center; }
.social-btn { width: 100%; margin-bottom: 1rem; background: var(--gray-100); color: var(--dark); font-weight: 600; display: flex; align-items: center; justify-content: center; gap: 0.75rem; }
.social-btn:hover { background: var(--gray-200); transform: none; }
.social-btn.facebook { background: #1877F2; color: white; }
.social-btn.apple { background: #000; color: white; }
.divider { margin: 2rem 0; position: relative; }
.divider::before { content: ""; position: absolute; left: 0; top: 50%; width: 100%; height: 1px; background: var(--gray-200); }
.divider span { position: relative; background: var(--light); padding: 0 1rem; color: var(--gray-600); font-size: 0.875rem; }
.form-group { margin-bottom: 1.5rem; text-align: left; }
.form-group label { display: block; margin-bottom: 0.5rem; font-weight: 600; font-size: 0.875rem; }
.form-control { width: 100%; padding: 0.75rem 1rem; border: 1px solid var(--gray-200); border-radius: var(--radius-sm); font-family: var(--font-main); font-size: 1rem; transition: border-color 0.2s; }
.form-control:focus { outline: none; border-color: var(--dark); }
.password-wrapper { position: relative; }
.toggle-password { position: absolute; right: 1rem; top: 50%; transform: translateY(-50%); background: none; border: none; cursor: pointer; color: var(--gray-600); }

/* Footer */
footer { background: var(--dark); color: var(--light); padding: 5rem 0 2rem; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 3rem; margin-bottom: 4rem; }
.footer-col h4 { color: var(--light); margin-bottom: 1.5rem; font-size: 1.1rem; }
.footer-col ul li { margin-bottom: 0.75rem; }
.footer-col ul li a { color: #A0A0A0; transition: color 0.2s; font-size: 0.95rem; }
.footer-col ul li a:hover { color: var(--light); }
.footer-bottom { border-top: 1px solid #333; padding-top: 2rem; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem; color: #A0A0A0; font-size: 0.875rem; }
.footer-bottom-links { display: flex; gap: 1.5rem; flex-wrap: wrap; }

/* Responsive */
@media (max-width: 1024px) {
  .carousel-item { flex: 0 0 calc(33.333% - 1rem); }
  .carousel-item.large { flex: 0 0 calc(50% - 1rem); }
  .masonry-grid { column-count: 2; }
}
@media (max-width: 768px) {
  h1 { font-size: 2.5rem; }
  h2 { font-size: 2rem; }
  .nav-links, .search-bar { display: none; }
  .carousel-item, .carousel-item.large { flex: 0 0 calc(85%); }
  .page-layout { flex-direction: column; }
  .sidebar { width: 100%; display: flex; overflow-x: auto; gap: 2rem; padding-bottom: 1rem; }
  .filter-group { flex: 0 0 auto; }
  .masonry-grid { column-count: 1; }

  .footer-col h4 { cursor: pointer; display: flex; justify-content: space-between; align-items: center; margin-bottom: 0; padding: 1rem 0; border-bottom: 1px solid #333; }
  .footer-col h4::after { content: '+'; font-size: 1.5rem; font-weight: 400; }
  .footer-col.active h4::after { content: '−'; }
  .footer-col ul { display: none; padding: 1rem 0; }
  .footer-col.active ul { display: block; }
}

